<template>
  <main class="paper-shell"><div class="paper-container search-container">
    <header class="paper-workspace-header"><div><div class="paper-page-eyebrow">Knowledge Base / Search</div><h1 class="paper-page-title">Search & Knowledge Base</h1><p class="paper-page-description">Search the collected corpus and inspect papers, extracted data points, knowledge, and methods.</p></div><div class="header-actions"><NuxtLink class="paper-button" to="/papers">Submission papers</NuxtLink><NuxtLink class="paper-button primary" to="/literature/workflow">Processing workflow</NuxtLink></div></header>
    <LiteratureKnowledgeNav />
    <nav class="record-tabs" aria-label="Knowledge base record types"><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" @click="setTab(item.id)">{{ item.label }}</button></nav>
    <section v-if="tab==='papers'" class="paper-panel admission-panel" aria-label="Knowledge base completeness filters">
      <div class="admission-copy"><strong>Knowledge-base readiness</strong><span>{{ admissionDescription }}</span></div>
      <div class="admission-controls">
        <div class="admission-tabs" role="group" aria-label="Record readiness">
          <button v-for="item in admissionViews" :key="item.id" type="button" :class="{active:admissionView===item.id}" @click="setAdmissionView(item.id)">{{ item.label }}</button>
        </div>
        <label>Completeness<select v-model="completenessLevel" @change="applyCompletenessLevel"><option value="">All levels in this view</option><option v-for="item in completenessLevels" :key="item.id" :value="item.id">{{ item.id }} · {{ item.label }}</option></select></label>
      </div>
    </section>
    <section class="paper-panel search-panel">
      <div class="search-panel-title"><div><strong>{{ tab==='papers'?'Advanced literature search':tabs.find(item=>item.id===tab)?.label }}</strong><span>{{ tab==='papers'?'Search the same fields and modes exposed by the original system.':'Search structured records extracted from processed PDFs.' }}</span></div><button type="button" @click="expanded=!expanded">{{ expanded?'Collapse':'Expand' }}</button></div>
      <form class="search-form" @submit.prevent="runSearch(true)">
        <template v-if="tab==='papers'">
          <div v-for="(row,index) in fieldRows" :key="index" class="field-row"><select v-model="row.field" aria-label="Search field"><option v-for="field in searchFields" :key="field.id" :value="field.id">{{ field.label }}</option></select><input v-model="row.value" :placeholder="row.field==='year'?'e.g. 2020-2024':`Enter ${fieldLabel(row.field).toLowerCase()}`" /><button type="button" :disabled="fieldRows.length===1" aria-label="Remove search row" @click="removeRow(index)">×</button></div>
          <div class="search-actions"><label>Mode<select v-model="mode"><option value="keyword">Keyword</option><option value="phrase">Phrase</option><option value="fuzzy">Fuzzy</option><option value="vector">Vector</option><option value="hybrid">Hybrid</option></select></label><button class="paper-button" type="button" :disabled="fieldRows.length>=6" @click="addRow">Add field</button><button class="paper-button primary" :disabled="pending">{{ pending?'Searching…':'Search' }}</button><button class="paper-button" type="button" @click="clearSearch">Clear</button></div>
          <div v-if="mode==='hybrid'" class="weight-grid"><label>Full-text weight <output>{{ ftsWeight.toFixed(2) }}</output><input v-model.number="ftsWeight" type="range" min="0" max="1" step="0.05" /></label><label>Vector weight <output>{{ vectorWeight.toFixed(2) }}</output><input v-model.number="vectorWeight" type="range" min="0" max="1" step="0.05" /></label></div>
          <div class="tier-filter"><span>Journal tier</span><label v-for="item in tiers" :key="item.id"><input v-model="filters.journal_tiers" type="checkbox" :value="item.id" /> {{ item.label }}</label></div>
          <div v-if="expanded" class="filter-grid"><label>Year from<input v-model="filters.year_from" type="number" /></label><label>Year to<input v-model="filters.year_to" type="number" /></label><label>Journal<input v-model="filters.journal" /></label><label>Author<input v-model="filters.author" /></label><label>Language<input v-model="filters.language" /></label><label>Source<input v-model="filters.source" /></label><label>DOI<input v-model="filters.doi" /></label><label>Sort<select v-model="sort"><option value="relevance">Relevance</option><option value="date_desc">Newest first</option><option value="date_asc">Oldest first</option></select></label></div>
        </template>
        <template v-else><div class="simple-search"><input v-model="simpleQuery" :placeholder="tabPlaceholder" /><button class="paper-button primary" :disabled="pending">{{ pending?'Searching…':'Search' }}</button><button class="paper-button" type="button" @click="clearSearch">Clear</button></div></template>
      </form>
      <p v-if="mode==='vector'||mode==='hybrid'" class="dependency-note">Vector retrieval is preserved from the original system. Results require generated embeddings and a configured Embedding API key.</p>
    </section>
    <p v-if="error" class="search-error">{{ error }}</p><p v-if="notice" class="search-notice">{{ notice }}</p>
    <div class="result-layout">
      <aside v-if="tab==='papers'&&facetGroups.length" class="paper-panel facet-panel"><div class="facet-heading"><strong>Refine results</strong><button @click="clearFacetFilters">Reset</button></div><section v-for="group in facetGroups" :key="group.id"><h2>{{ group.label }}</h2><button v-for="item in group.items.slice(0,20)" :key="item.key" :class="{selected:isFacetSelected(group.id,item.key)}" @click="toggleFacet(group.id,item.key)"><span>{{ item.label||item.key||'Unknown' }}</span><strong>{{ item.count }}</strong></button></section></aside>
      <section class="paper-panel results-panel"><div class="results-heading"><div><strong>{{ resultTitle }}</strong><span>{{ total.toLocaleString() }} results</span></div><label v-if="tab==='papers'&&isDefaultBrowse">Sort<select v-model="defaultSort" @change="runSearch(true)"><option value="year_desc">Newest first</option><option value="year_asc">Oldest first</option><option value="citations_desc">Most cited</option><option value="title_asc">Title A–Z</option></select></label></div>
        <div v-if="pending" class="empty-state">Loading records…</div><div v-else-if="!rows.length" class="empty-state"><strong>No matching records</strong><span>Try a broader query or remove one of the filters.</span></div>
        <template v-else><article v-for="(row,index) in rows" :key="row.id||row.paper_id||index" class="result-row" @click="openRow(row)"><div><div class="result-title-line"><h2>{{ rowTitle(row,index) }}</h2><span v-if="row.completeness?.level" class="completeness-badge" :class="row.completeness.level.toLowerCase()">{{ row.completeness.level }}</span></div><p>{{ rowSummary(row) }}</p><div class="result-meta"><span v-for="item in rowMeta(row)" :key="item">{{ item }}</span></div><p v-if="row.completeness?.warnings?.includes('visual_content_missing')" class="result-warning">Visual content was not extracted; verify figures and tables in the source PDF.</p></div><strong v-if="row.score!=null" class="score">{{ Number(row.score).toFixed(3) }}</strong></article><nav class="pagination" aria-label="Search result pages"><button :disabled="offset===0" @click="changePage(-1)">Previous</button><span>Page {{ currentPage }} of {{ pageCount }}</span><button :disabled="offset+limit>=total" @click="changePage(1)">Next</button></nav></template>
      </section>
    </div>
  </div></main>
</template>

<script setup>
import '~/assets/paper-platform.css'
import LiteratureKnowledgeNav from '~/components/LiteratureKnowledgeNav.vue'
const config=useRuntimeConfig(),route=useRoute(),router=useRouter();useHead({title:'Search & Knowledge Base - OpenIsle'})
const tabs=[{id:'papers',label:'Papers'},{id:'data_points',label:'Data Points'},{id:'knowledge',label:'Knowledge'},{id:'methods',label:'Methods'}]
const admissionViews=[{id:'usable',label:'Usable knowledge'},{id:'pending',label:'Pending processing'},{id:'all',label:'All records'}]
const completenessLevels=[{id:'L0',label:'Metadata only'},{id:'L1',label:'PDF available'},{id:'L2',label:'Parsed full text'},{id:'L3',label:'Knowledge and methods'},{id:'L4',label:'Data extraction complete'}]
const searchFields=[{id:'all',label:'All fields'},{id:'title',label:'Title'},{id:'abstract',label:'Abstract'},{id:'keywords',label:'Keywords'},{id:'author',label:'Author'},{id:'journal',label:'Journal'},{id:'doi',label:'DOI'},{id:'year',label:'Year'},{id:'fulltext',label:'Full text'}]
const tiers=[{id:'tier1',label:'T1'},{id:'tier2',label:'T2'},{id:'tier3',label:'T3'},{id:'other',label:'Unrated'}]
const initialSort=String(route.query.sort||'');const initialAdmissionView=['usable','pending','all'].includes(String(route.query.view))?String(route.query.view):'usable';const initialLevel=/^L[0-4]$/.test(String(route.query.level||'').toUpperCase())?String(route.query.level).toUpperCase():'';const tab=ref(tabs.some(x=>x.id===route.query.tab)?String(route.query.tab):'papers'),mode=ref(String(route.query.mode||'keyword')),expanded=ref(false),pending=ref(false),error=ref(''),notice=ref(''),payload=ref(null),simpleQuery=ref(String(route.query.q||'')),offset=ref(Math.max(0,Number(route.query.offset)||0)),limit=20,sort=ref(['relevance','date_desc','date_asc'].includes(initialSort)?initialSort:'relevance'),defaultSort=ref(['year_desc','year_asc','citations_desc','title_asc'].includes(initialSort)?initialSort:'year_desc'),ftsWeight=ref(Number(route.query.fts_weight)||.4),vectorWeight=ref(Number(route.query.vector_weight)||.6),admissionView=ref(initialAdmissionView),completenessLevel=ref(initialLevel)
const fieldRows=ref([{field:String(route.query.field1||'all'),value:String(route.query.q1||route.query.q||'')}]);for(let i=2;i<=6;i++)if(route.query[`field${i}`])fieldRows.value.push({field:String(route.query[`field${i}`]),value:String(route.query[`q${i}`]||'')})
const filters=reactive({year_from:String(route.query.year_from||''),year_to:String(route.query.year_to||''),journal:String(route.query.journal||''),author:String(route.query.author||''),language:String(route.query.language||''),source:String(route.query.source||''),doi:String(route.query.doi||''),journal_tiers:String(route.query.journal_tiers||'').split(',').filter(Boolean)})
const endpoint=path=>`${config.public.apiBaseUrl}/api/literature/explore${path}`
const activeQuery=computed(()=>tab.value==='papers'?(fieldRows.value.find(r=>r.field==='all'&&r.value.trim())||fieldRows.value.find(r=>r.value.trim()))?.value.trim()||'':simpleQuery.value.trim())
const activeFields=computed(()=>[...new Set(fieldRows.value.filter(r=>r.value.trim()&&r.field!=='all'&&r.field!=='year').map(r=>r.field))])
const hasFilters=computed(()=>Object.entries(filters).some(([key,value])=>key==='journal_tiers'?value.length:String(value).trim()))
const isDefaultBrowse=computed(()=>tab.value==='papers'&&!activeQuery.value&&!hasFilters.value)
const rows=computed(()=>{const p=payload.value||{};if(tab.value==='papers')return p.hits||p.papers||p.results||[];return p[tab.value]||[]})
const total=computed(()=>Number(payload.value?.total??rows.value.length)),currentPage=computed(()=>Math.floor(offset.value/limit)+1),pageCount=computed(()=>Math.max(1,Math.ceil(total.value/limit)))
const facets=computed(()=>payload.value?.aggregations||{}),facetGroups=computed(()=>[{id:'journal_tier',label:'Journal tier'},{id:'year',label:'Year'},{id:'journal',label:'Journal'},{id:'language',label:'Language'},{id:'source',label:'Source'},{id:'author',label:'Author'},{id:'keyword',label:'Keyword'}].map(x=>({...x,items:Array.isArray(facets.value[x.id])?facets.value[x.id]:[]})).filter(x=>x.items.length))
const tabPlaceholder=computed(()=>({data_points:'Metric name',knowledge:'Research question, claim, or finding',methods:'Method, data source, model, or algorithm'})[tab.value]||'Search'),resultTitle=computed(()=>tabs.find(x=>x.id===tab.value)?.label||'Results')
const admissionDescription=computed(()=>completenessLevel.value?`${completenessLevels.find(item=>item.id===completenessLevel.value)?.label||'Selected level'} records only.`:({usable:'Only records with reliable parsed full text (L2–L4) enter the default knowledge base.',pending:'Metadata-only and PDF-only records that still require processing.',all:'Administrative view of every collected, non-placeholder record.'})[admissionView.value])
const fieldLabel=id=>searchFields.find(x=>x.id===id)?.label||'Field';const addRow=()=>{if(fieldRows.value.length<6)fieldRows.value.push({field:'all',value:''})};const removeRow=i=>{if(fieldRows.value.length>1)fieldRows.value.splice(i,1)}
const buildPaperParams=()=>{const p=new URLSearchParams({limit:String(limit),offset:String(offset.value)});if(activeQuery.value)p.set('q',activeQuery.value);if(mode.value)p.set('mode',mode.value);if(activeFields.value.length)p.set('fields',activeFields.value.join(','));for(const key of ['year_from','year_to','journal','author','language','source','doi'])if(filters[key])p.set(key,filters[key]);if(filters.journal_tiers.length)p.set('journal_tiers',filters.journal_tiers.join(','));p.set('sort',sort.value);return p}
const syncRoute=()=>{const q={tab:tab.value==='papers'?undefined:tab.value,mode:tab.value==='papers'&&mode.value!=='keyword'?mode.value:undefined,offset:offset.value||undefined,sort:tab.value==='papers'?(isDefaultBrowse.value?(defaultSort.value==='year_desc'?undefined:defaultSort.value):(sort.value==='relevance'?undefined:sort.value)):undefined,view:tab.value==='papers'&&admissionView.value!=='usable'?admissionView.value:undefined,level:tab.value==='papers'&&completenessLevel.value?completenessLevel.value:undefined,fts_weight:mode.value==='hybrid'&&ftsWeight.value!==.4?ftsWeight.value:undefined,vector_weight:mode.value==='hybrid'&&vectorWeight.value!==.6?vectorWeight.value:undefined};fieldRows.value.forEach((row,i)=>{if(row.field!=='all'||row.value){q[`field${i+1}`]=row.field;q[`q${i+1}`]=row.value||undefined}});if(tab.value!=='papers'&&simpleQuery.value)q.q=simpleQuery.value;for(const [key,value] of Object.entries(filters))if(tab.value==='papers'&&(Array.isArray(value)?value.length:value))q[key]=Array.isArray(value)?value.join(','):value;return router.replace({query:q})}
const runSearch=async(reset=false)=>{if(reset)offset.value=0;pending.value=true;error.value='';notice.value='';try{if(tab.value==='papers'){if(mode.value==='vector'||mode.value==='hybrid'){const p=new URLSearchParams({q:activeQuery.value,top_k:String(limit),offset:String(offset.value)});if(mode.value==='hybrid'){p.set('fts_weight',String(ftsWeight.value));p.set('vector_weight',String(vectorWeight.value))}const data=await $fetch(`${endpoint(mode.value==='vector'?'/vector/search':'/hybrid/search')}?${p}`);payload.value={...data,total:data.total??data.results?.length??0};if(data.available===false)notice.value=data.message||'Vector search is not configured.'}else if(isDefaultBrowse.value){const p=new URLSearchParams({limit:String(limit),offset:String(offset.value),sort:defaultSort.value,view:admissionView.value});if(completenessLevel.value)p.set('level',completenessLevel.value);payload.value=await $fetch(`${endpoint('/papers/list')}?${p}`)}else{payload.value=await $fetch(`${endpoint('/search')}?${buildPaperParams()}`);notice.value='Readiness filters apply to the default corpus view; advanced search returns matching records from the full corpus.'}}else{const p=new URLSearchParams({limit:String(limit),offset:String(offset.value)});if(simpleQuery.value.trim())p.set(tab.value==='data_points'?'metric_name':'q',simpleQuery.value.trim());payload.value=await $fetch(`${endpoint(`/${tab.value}/list`)}?${p}`)}await syncRoute()}catch(cause){error.value=cause?.data?.message||cause?.data?.error||cause?.message||'Search failed.';payload.value=null}finally{pending.value=false}}
const setAdmissionView=value=>{admissionView.value=value;completenessLevel.value='';runSearch(true)};const applyCompletenessLevel=()=>{if(completenessLevel.value==='L0'||completenessLevel.value==='L1')admissionView.value='pending';else if(completenessLevel.value)admissionView.value='usable';runSearch(true)}
const setTab=value=>{tab.value=value;offset.value=0;runSearch()};const changePage=direction=>{offset.value=Math.max(0,offset.value+direction*limit);runSearch()};const clearSearch=()=>{fieldRows.value=[{field:'all',value:''}];simpleQuery.value='';mode.value='keyword';Object.assign(filters,{year_from:'',year_to:'',journal:'',author:'',language:'',source:'',doi:'',journal_tiers:[]});offset.value=0;runSearch()};const clearFacetFilters=()=>{Object.assign(filters,{year_from:'',year_to:'',journal:'',author:'',language:'',source:'',doi:'',journal_tiers:[]});runSearch(true)}
const isFacetSelected=(group,key)=>group==='journal_tier'?filters.journal_tiers.includes(key):group==='year'?(filters.year_from===key&&filters.year_to===key):String(filters[group]||'')===String(key)
const toggleFacet=(group,key)=>{if(group==='journal_tier'){const i=filters.journal_tiers.indexOf(key);i>=0?filters.journal_tiers.splice(i,1):filters.journal_tiers.push(key)}else if(group==='year'){if(filters.year_from===key&&filters.year_to===key){filters.year_from='';filters.year_to=''}else{filters.year_from=key;filters.year_to=key}}else filters[group]=String(filters[group]||'')===String(key)?'':key;runSearch(true)}
const strip=value=>String(value||'').replace(/<[^>]*>/g,'').replace(/\s+/g,' ').trim();const formatAuthors=value=>{const authors=Array.isArray(value)?value:[value];return authors.filter(Boolean).map(author=>typeof author==='string'?author:[author.given,author.family].filter(Boolean).join(' ')||author.full_name||author.name||'').filter(Boolean).join(', ')};const rowTitle=(row,index)=>strip(row.title||row.paper_title||row.metric_name||row.research_question||row.methodology||`Result ${index+1}`);const rowSummary=row=>strip(row.abstract_snippet||row.abstract||row.context||row.core_answer||row.methodology||row.research_question||'').slice(0,360);const rowMeta=row=>[formatAuthors(row.authors||row.author),row.journal,row.published_year||row.year,row.journal_tier?String(row.journal_tier).toUpperCase():null,row.source,row.citation_count!=null?`${row.citation_count} citations`:null,Array.isArray(row.keywords)?row.keywords.slice(0,5).join(' · '):row.keywords,row.unit,row.confidence,row.key_claims_count!=null?`${row.key_claims_count} claims`:null].filter(Boolean).map(strip);const openRow=row=>{const id=row.paper_id||row.id;if(id)router.push(`/literature/${id}`)}
onMounted(()=>runSearch())
</script>

<style scoped>
