.admission-panel{display:grid;grid-template-columns:minmax(260px,1fr) auto;gap:20px;align-items:center;margin-bottom:12px;padding:14px 16px}.admission-copy{display:grid;gap:4px}.admission-copy span{color:var(--paper-muted);font-size:11px;line-height:1.5}.admission-controls{display:flex;align-items:end;gap:12px}.admission-tabs{display:flex;border:1px solid var(--paper-line)}.admission-tabs button{border:0;border-right:1px solid var(--paper-line);background:#fff;padding:9px 12px;color:var(--paper-muted);font-size:11px;font-weight:750;cursor:pointer}.admission-tabs button:last-child{border-right:0}.admission-tabs button.active{background:var(--paper-teal);color:#fff}.admission-controls label{display:grid;gap:4px;color:var(--paper-muted);font-size:10px;font-weight:750}.admission-controls select{min-height:35px;border:1px solid var(--paper-line);background:#fff;padding:6px 9px}
.result-title-line{display:flex;gap:9px;align-items:flex-start}.result-title-line h2{flex:1}.completeness-badge{flex:0 0 auto;border:1px solid var(--paper-line);padding:3px 6px;color:var(--paper-muted);font-size:9px;font-weight:850;letter-spacing:.06em}.completeness-badge.l2,.completeness-badge.l3,.completeness-badge.l4{border-color:#8cb9aa;background:#edf7f2;color:#22604c}.result-row .result-warning{display:block;margin-top:8px;color:#8a5a12;font-size:10px}
.search-container{max-width:1280px}.header-actions,.search-actions,.tier-filter{display:flex;flex-wrap:wrap;gap:8px}.record-tabs{display:flex;gap:1px;margin-bottom:12px;border:1px solid var(--paper-line);background:var(--paper-line)}.record-tabs button{flex:1;border:0;padding:12px;background:#fff;color:var(--paper-muted);font-weight:800;cursor:pointer}.record-tabs button.active{background:var(--paper-teal);color:#fff}.search-panel{overflow:hidden;margin-bottom:14px}.search-panel-title,.results-heading,.facet-heading{display:flex;justify-content:space-between;align-items:center;padding:13px 16px;border-bottom:1px solid var(--paper-line)}.search-panel-title div,.results-heading>div{display:grid;gap:3px}.search-panel-title span,.results-heading span{color:var(--paper-muted);font-size:11px}.search-panel-title button,.facet-heading button{border:0;background:none;color:var(--paper-teal);font-weight:750;cursor:pointer}.search-form{display:grid;gap:9px;padding:15px}.field-row{display:grid;grid-template-columns:145px minmax(0,1fr) 38px;gap:7px}.field-row input,.field-row select,.filter-grid input,.filter-grid select,.search-actions select,.simple-search input,.results-heading select{min-height:39px;border:1px solid var(--paper-line);background:#fff;padding:8px 10px}.field-row button{border:1px solid var(--paper-line);background:#fff;color:var(--paper-muted);font-size:18px}.search-actions{align-items:end}.search-actions label,.filter-grid label{display:grid;gap:4px;color:var(--paper-muted);font-size:10px;font-weight:750}.weight-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;padding:10px;background:var(--paper-panel-subtle)}.weight-grid label{display:grid;grid-template-columns:1fr auto;gap:6px;color:var(--paper-muted);font-size:11px}.weight-grid input{grid-column:1/-1}.tier-filter{align-items:center;padding-top:8px;border-top:1px solid var(--paper-line);color:var(--paper-muted);font-size:11px}.tier-filter label{display:flex;align-items:center;gap:4px}.filter-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;padding-top:9px;border-top:1px solid var(--paper-line)}.simple-search{display:grid;grid-template-columns:1fr auto auto;gap:8px}.dependency-note,.search-notice,.search-error{margin:0;padding:10px 14px;border-top:1px solid #ead9a6;background:#fff8e6;color:#71510b;font-size:11px}.search-error{margin-bottom:12px;border:0;background:#fff4f2;color:#8b3028}.search-notice{margin-bottom:12px;border:0}.result-layout{display:grid;grid-template-columns:235px minmax(0,1fr);gap:14px}.facet-panel{align-self:start;overflow:hidden}.facet-panel section{padding:13px 14px;border-top:1px solid var(--paper-line)}.facet-panel h2{margin:0 0 7px;color:var(--paper-muted);font-size:10px;text-transform:uppercase;letter-spacing:.06em}.facet-panel section button{display:flex;justify-content:space-between;width:100%;border:0;padding:6px;background:none;color:var(--paper-muted);font-size:11px;text-align:left;cursor:pointer}.facet-panel section button.selected{background:#e9f4f6;color:var(--paper-teal);font-weight:750}.results-panel{overflow:hidden}.results-heading label{display:flex;align-items:center;gap:7px;color:var(--paper-muted);font-size:10px}.result-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:15px;padding:16px 18px;border-bottom:1px solid var(--paper-line);cursor:pointer}.result-row:hover{background:#f5f9fa}.result-row h2{margin:0 0 6px;font:500 18px Georgia,serif}.result-row p{display:-webkit-box;overflow:hidden;margin:0;color:var(--paper-muted);font-size:12px;line-height:1.5;-webkit-box-orient:vertical;-webkit-line-clamp:3}.result-meta{display:flex;flex-wrap:wrap;gap:6px 14px;margin-top:9px;color:var(--paper-muted);font-size:10px}.score{align-self:start;color:var(--paper-teal);font-size:11px}.empty-state{display:grid;gap:5px;padding:60px;text-align:center;color:var(--paper-muted)}.pagination{display:flex;justify-content:center;align-items:center;gap:14px;padding:14px}.pagination button{border:1px solid var(--paper-line);background:#fff;padding:7px 11px;color:var(--paper-ink)}.pagination span{color:var(--paper-muted);font-size:11px}@media(max-width:900px){.result-layout{grid-template-columns:1fr}.facet-panel{display:none}.filter-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.field-row{grid-template-columns:110px minmax(0,1fr) 36px}.filter-grid,.weight-grid{grid-template-columns:1fr}.simple-search{grid-template-columns:1fr}.record-tabs button{min-width:100px}.record-tabs{overflow:auto}}
@media(max-width:900px){.admission-panel{grid-template-columns:1fr}.admission-controls{align-items:stretch;flex-direction:column}}
</style>
